'use strict';

/**
* LAPACK routine to compute the singular value decomposition of a 2x2 upper triangular matrix.
*
* @module @stdlib/lapack/base/dlasv2
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlasv2 = require( '@stdlib/lapack/base/dlasv2' );
*
* var out = new Float64Array( 6 );
*
* dlasv2( 2.0, 3.0, 4.0, out );
* // out => <Float64Array>[ ~1.5513, ~5.1569, ~0.9665, ~0.2567, ~0.7497, ~0.6618 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlasv2 = require( '@stdlib/lapack/base/dlasv2' );
*
* var out = new Float64Array( 6 );
*
* dlasv2.ndarray( 2.0, 3.0, 4.0, out, 1, 0 );
* // out => <Float64Array>[ ~1.5513, ~5.1569, ~0.9665, ~0.2567, ~0.7497, ~0.6618 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dlasv2;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlasv2 = main;
} else {
	dlasv2 = tmp;
}


// EXPORTS //

module.exports = dlasv2;
